<script setup lang="ts">
const api=window.teachshelf;
import {computed,ref} from 'vue';
import {Archive,CalendarDays,Check,Clock3,MoreHorizontal,Plus,Repeat2,Search,Trash2} from 'lucide-vue-next';
import {dateMs,swiftNow} from '../../shared/model';
import type {StudyTask} from '../../shared/model';
import {useLibrary} from '../stores/library';
import TaskEditor from '../components/TaskEditor.vue';
const store=useLibrary(),filter=ref('active'),query=ref(''),courseID=ref(''),editing=ref<StudyTask|null|undefined>(undefined);
const plans=computed(()=>store.state.tasks.filter(t=>(store.route!=='pending'||(!t.completedAt&&!t.cancelledAt&&!t.archivedAt&&t.completionRequired!==false))&&(filter.value==='all'||(filter.value==='archived'?!!t.archivedAt:!t.archivedAt))&&(!courseID.value||t.courseID===courseID.value)&&[t.title,t.content,t.kind].join(' ').toLowerCase().includes(query.value.toLowerCase())).sort((a,b)=>dateMs(a.deadline??a.startsAt)-dateMs(b.deadline??b.startsAt)));
function label(value:number|string){return new Date(dateMs(value)).toLocaleString('zh-CN',{month:'long',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit'});}
async function complete(task:StudyTask){await store.change(()=>api.saveTask({id:task.id,title:task.title,completedAt:task.completedAt?undefined:swiftNow()}),task.completedAt?'计划已恢复为待完成':'计划已完成');}
async function archive(task:StudyTask){await store.change(()=>api.saveTask({id:task.id,title:task.title,archivedAt:task.archivedAt?undefined:swiftNow()}),'计划归档状态已更新');}
async function remove(task:StudyTask){if(await store.confirm('删除计划？',`将删除“${task.title}”，关联课程和资料不会删除。`,'删除计划'))await store.change(()=>api.deleteTasks([task.id]),'计划已删除');}
defineExpose({create:()=>{editing.value=null;}});
</script>
<template><section class="workspace"><header class="workspace-header"><div class="heading-block"><div class="heading-line"><h1>{{store.title}}</h1><span class="subtle-count">{{plans.length}} 项</span></div><p>安排学习与作业，让每一项计划有迹可循。</p></div><div class="toolbar-controls"><button @click="store.navigate('timetable')"><CalendarDays :size="16"/>查看课表</button><button class="primary" @click="editing=null"><Plus :size="16"/>新建计划</button></div></header><div class="filter-bar"><label class="search-field"><Search :size="16"/><input v-model="query" placeholder="搜索计划名称与内容" aria-label="搜索计划"/></label><select v-model="courseID" aria-label="计划课程筛选"><option value="">全部课程</option><option v-for="c in store.state.courses" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="filter" aria-label="计划状态筛选"><option value="active">当前计划</option><option value="archived">已归档</option><option value="all">全部计划</option></select></div><div class="plans-scroll"><div v-if="!plans.length" class="empty-state"><CalendarDays :size="43"/><h2>还没有符合条件的计划</h2><p>创建任务，关联课程、资料和截止时间。</p><button class="primary" @click="editing=null">新建计划</button></div><div v-for="task in plans" :key="task.id" class="plan-row" :class="{completed:task.completedAt,cancelled:task.cancelledAt}"><button class="complete-button" :class="{checked:task.completedAt}" :aria-label="(task.completedAt?'恢复计划 ':'完成计划 ')+task.title" :disabled="!!task.repeatRule||task.origin==='fixed'||task.completionRequired===false||!!task.cancelledAt" :title="task.repeatRule?'重复计划的单次完成尚未迁移':undefined" @click="complete(task)"><Check v-if="task.completedAt" :size="15"/></button><button class="plan-content" @click="editing=task"><div class="plan-title"><strong>{{task.title}}</strong><span class="tag">{{task.kind}}</span><Repeat2 v-if="task.repeatRule" :size="14"/><span v-if="task.archivedAt" class="tag">已归档</span><span v-if="task.cancelledAt" class="tag">已取消</span></div><p v-if="task.content" class="plan-description">{{task.content}}</p><div class="plan-meta"><span v-if="task.courseID"><span class="inline-dot" :style="{background:store.state.courses.find(c=>c.id===task.courseID)?.colorHex}"/>{{store.state.courses.find(c=>c.id===task.courseID)?.name??task.courseNameSnapshot}}</span><span><Clock3 :size="12"/>{{task.deadline?'截止：':'执行：'}}{{label(task.deadline??task.startsAt)}}</span><span v-if="task.location">{{task.location}}</span><span v-if="task.materialIDs.length">{{task.materialIDs.length}} 份关联资料</span></div></button><div class="plan-actions"><button class="icon-button" :aria-label="task.archivedAt?'恢复归档计划':'归档计划'" :title="task.archivedAt?'恢复归档计划':'归档计划'" @click="archive(task)"><Archive :size="16"/></button><button class="icon-button danger-text" aria-label="删除计划" @click="remove(task)"><Trash2 :size="16"/></button></div></div><div v-if="store.state.timetableTerms.length" class="info-note"><CalendarDays :size="17"/><div>资料库中 {{store.state.timetableTerms.length}} 个课表学期已完整保留。<p>点击“查看课表”可按周查看、设置学期并取消或恢复单次课程。调课编辑、月视图及重复计划的单次操作尚未迁移。</p></div></div></div><TaskEditor v-if="editing!==undefined" :task="editing??undefined" @close="editing=undefined"/></section></template>
